import type { GuruCard } from "./guruSolver";

/**
 * Prepared answers for the most common Class 9-10 questions (Sindh Textbook Board syllabus).
 * Each entry: the phrases that identify it (English + Roman Urdu), a Roman Urdu "samjho", the board-English answer,
 * formula/unit when relevant, an examiner tip and a check question. Answered instantly, no AI.
 */
interface Entry {
  terms: string[]; // any of these phrases (after normalising) identifies the entry; longer = more specific
  subject: string;
  grade: number;
  title: string;
  samjho: string;
  board: string;
  formula?: string;
  unit?: string;
  tip: string;
  check: string;
}

const E = (subject: string, grade: number, title: string, terms: string[], samjho: string, board: string, tip: string, check: string, formula?: string, unit?: string): Entry =>
  ({ subject, grade, title, terms, samjho, board, tip, check, formula, unit });

