// ---------------- Matching ----------------
const SYNONYMS: [RegExp, string][] = [
  [/\bqanoon\b|\bkanoon\b|\bqanun\b/g, "law"],
  [/\bfarq\b|\bfark\b/g, "difference"],
  [/\braftar\b|\braftaar\b/g, "speed"],
  [/\bquwwat\b|\bquwat\b/g, "force"],
  [/\btaqat\b|\btaaqat\b/g, "power"],
  [/\bwazan\b/g, "weight"],
  [/\bphephre\b|\bphephron\b/g, "lungs"],
  [/\bgurda\b|\bgurde\b/g, "kidney"],
  [/\baankh\b|\bankh\b/g, "eye"],
  [/\bkhalia\b|\bkhaliya\b/g, "cell"],
  [/\btezaab\b|\btezab\b/g, "acid"],
  [/\bnamak\b/g, "salt"],
  [/\bbijli\b/g, "electric"],
  [/\broshni\b/g, "light"],
  [/\bawaaz\b|\bawaz\b/g, "sound"],
  [/\bgoonj\b/g, "echo"],
  [/\bsaans\b/g, "breathing"],
  [/\bandaza\b/g, "hypothesis"],
  [/\bayena\b|\baina\b|\baaina\b/g, "mirror"],
  [/\baur\b|\bor\b|\bvs\b|\bversus\b/g, "and"],
  [/\bmein\b|\bmain\b|\bka\b|\bki\b|\bke\b|\bkya\b|\bhai\b|\bhain\b|\bbatao\b|\bsamjhao\b|\bexplain\b/g, " "],
  [/\bpehla\b|\bpehle\b/g, "first"],
  [/\bdoosra\b|\bdusra\b/g, "second"],
  [/\bteesra\b|\btisra\b/g, "third"],
  [/[’'`]/g, ""],
];

export function normalise(text: string): string {
  let t = " " + text.toLowerCase().replace(/[?!.,;:()"]/g, " ").replace(/\s+/g, " ") + " ";
  for (const [re, rep] of SYNONYMS) t = t.replace(re, rep);
  return t.replace(/\s+/g, " ");
}

// Terms are normalised the same way as questions, so Roman Urdu terms ("pehla qanoon") match after conversion
const NORMALISED_TERMS = new Map<string, string>();
const normTerm = (k: string) => {
  let v = NORMALISED_TERMS.get(k);
  if (v === undefined) {
    v = normalise(k).trim();
    NORMALISED_TERMS.set(k, v);
  }
  return v;
};

/** Best bank entry for the question, or null if nothing matches well enough. */
export function matchBank(question: string, grade?: number): GuruCard | null {
  const t = normalise(question);
  let best: { e: Entry; score: number } | null = null;
  for (const e of BANK) {
    for (const term of e.terms) {
      const k = normTerm(term);
      if (!k) continue;
      // Short terms (e.g. "ph", "shm") must match as a whole word; longer ones may match inside text
      const hit = k.length <= 3 ? new RegExp(`\\b${k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`).test(t) : t.includes(k);
      if (!hit) continue;
      let score = k.length;
      if (grade && e.grade === grade) score += 2;
      if (!best || score > best.score) best = { e, score };
    }
  }
  if (!best) return null;
  const e = best.e;
  return {
    headline: `📘 ${e.title} (Class ${e.grade} ${e.subject})`,
    explanation: `Samjho: ${e.samjho}\n\n📝 Board answer:\n${e.board}`,
    formula: e.formula,
    unit: e.unit,
    stepTip: e.tip,
    challengeQuestion: e.check,
    source: "bank",
  };
}
